package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.StatusAtivo; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="categoria_produto") public class CategoriaProdutoEntity { @Id public UUID id; @Column(name="empresa_id",nullable=false) public UUID empresaId; @Column(name="categoria_pai_id") public UUID categoriaPaiId; @Column(nullable=false,length=100) public String nome; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="status_ativo") public StatusAtivo status; @Column(name="created_at",nullable=false) public Instant criadoEm; public CategoriaProdutoEntity() {} }
